fn shell_game(n: i32, x: i8) -> i8 {
    // number of complete (odd,even) pairs
    let pairs = n / 2;
    // reduce the cycle exponent mod 3
    let rem = (pairs % 3) as u8;
    // start at the initial position
    let mut pos = x;
    // apply the 3-cycle (0→2→1→0) rem times
    match rem {
        0 => { /* identity: do nothing */ }
        1 => { // one application of the cycle
            pos = match pos {
                0 => 2,
                1 => 0,
                2 => 1,
                _ => pos, // should not happen if input is 0..2
            };
        }
        2 => { // two applications = cycle^2 = (0→1→2→0)
            pos = match pos {
                0 => 1,
                1 => 2,
                2 => 0,
                _ => pos,
            };
        }
        _ => unreachable!(),
    }
    // if n is odd, we have one extra odd‐move = swap(0,1)
    if n % 2 != 0 {
        pos = match pos {
            0 => 1,
            1 => 0,
            2 => 2,
            _ => pos,
        };
    }
    pos
}

#[cfg(test)]
mod tests {
    use super::shell_game;

    #[test]
    fn small_examples() {
        // No moves: stays where it is
        assert_eq!(shell_game(0, 0), 0);
        assert_eq!(shell_game(0, 1), 1);
        assert_eq!(shell_game(0, 2), 2);

        // One move = odd swap(0,1)
        assert_eq!(shell_game(1, 0), 1);
        assert_eq!(shell_game(1, 1), 0);
        assert_eq!(shell_game(1, 2), 2);

        // Two moves = odd then even
        // odd: swap(0,1), even: swap(1,2)
        // so 0→1→1, 1→0→0, 2→2→1
        assert_eq!(shell_game(2, 0), 1);
        assert_eq!(shell_game(2, 1), 0);
        assert_eq!(shell_game(2, 2), 1);

        // Three moves = pair + extra odd
        // This is cycle (0→2→1) then swap(0,1)
        assert_eq!(shell_game(3, 0), 1); // 0→2→?→1
        assert_eq!(shell_game(3, 1), 2);
        assert_eq!(shell_game(3, 2), 2);

        // Check a longer sequence by brute force
        for start in 0..3 {
            for n in 0..20 {
                // brute‐force simulate
                let mut bf = start;
                for i in 1..=n {
                    if i % 2 == 1 {
                        // odd step: swap 0<->1
                        if bf == 0 { bf = 1 }
                        else if bf == 1 { bf = 0 }
                    } else {
                        // even step: swap 1<->2
                        if bf == 1 { bf = 2 }
                        else if bf == 2 { bf = 1 }
                    }
                }
                assert_eq!(bf, shell_game(n, start));
            }
        }
    }
}